def check_magic_sequence(x):
    """Check if x is a valid magic sequence."""
    n = len(x)
    for i in range(n):
        count = x.count(i)
        if x[i] != count:
            return False
    return True

# Brute force search for magic sequence of length 6
# Each x[i] can be 0 to 6
def find_magic_sequence(n):
    from itertools import product
    for x in product(range(n+1), repeat=n):
        if check_magic_sequence(list(x)):
            return list(x)
    return None

result = find_magic_sequence(6)
print(f"Result: {result}")

def find_magic_sequence_constrained(n):
    """Find magic sequence with constraints."""
    from itertools import product

    # Constraints:
    # sum(x[i]) = n
    # sum(i * x[i]) = n

    for x in product(range(n+1), repeat=n):
        if sum(x) != n:
            continue
        if sum(i * x[i] for i in range(n)) != n:
            continue
        # Check magic property
        valid = True
        for i in range(n):
            if x[i] != x.count(i):
                valid = False
                break
        if valid:
            return list(x)
    return None

result = find_magic_sequence_constrained(6)
print(f"Result: {result}")

