def find_magic_sequence_smart(n):
    # x[i] = count of i in sequence
    # sum(x) = n
    # sum(i*x[i]) = n

    # Generate all partitions of n into n parts
    def generate_partitions(n, k):
        if k == 1:
            yield (n,)
        else:
            for i in range(n + 1):
                for rest in generate_partitions(n - i, k - 1):
                    yield (i,) + rest

    for x in generate_partitions(n, n):
        if sum(i * x[i] for i in range(n)) != n:
            continue
        # Check magic property
        valid = True
        for i in range(n):
            if x[i] != x.count(i):
                valid = False
                break
        if valid:
            return list(x)
    return None

