def find_magic_sequence_cp(n):
    solutions = []
    def search(idx, remaining_sum, remaining_weight, current):
        if idx == n:
            if remaining_sum == 0 and remaining_weight == 0:
                # Check magic property
                valid = True
                for i in range(n):
                    if current[i] != current.count(i):
                        valid = False
                        break
                if valid:
                    solutions.append(list(current))
            return

        max_val = min(remaining_sum, n)
        for v in range(max_val + 1):
            if idx * v > remaining_weight:
                break
            current.append(v)
            search(idx + 1, remaining_sum - v, remaining_weight - idx * v, current)
            current.pop()

    search(0, n, n, [])
    return solutions

for n in range(1, 10):
    result = find_magic_sequence_cp(n)
    print(f"n={n}: {result}")
